    '.xpsw-foot{display:flex;justify-content:flex-end;gap:8px;padding:10px 14px;background:#ece9d8;border-top:1px solid #d5d2c6}',
    '.xpsw-btn{min-width:80px;height:23px;padding:0 12px;border:1px solid #7f9db9;border-radius:3px;cursor:pointer;font:12px Tahoma,"Microsoft YaHei",sans-serif;background:linear-gradient(180deg,#fff,#ece9d8 55%,#ddd6c3)}',
    '.xpsw-btn:hover{border-color:#e5a50a;background:linear-gradient(180deg,#fff,#fdf3d6 55%,#f6e5ae)}',
