    '.xpsw-ic{width:14px;height:11px;flex:0 0 auto;margin-right:5px;border-radius:1px;box-sizing:border-box;border:1px solid #c9a13a;background:#f6c95c}',
    '.xpsw-ic.drive{border-color:#8c97a5;background:linear-gradient(180deg,#eef1f5,#cfd6df)}',
